import 'dart:convert'; import '../core/agent_models.dart'; import 'tool.dart';
class DataTool extends AgentTool {
  String get name=>'data'; String get description=>'تحليل JSON وCSV محلياً.'; Map<String,dynamic> get parameters=>const {'action':'parse_json | parse_csv | filter','data':'string','filter_key':'string','filter_value':'string'};
  Future<StepResult> execute(Map<String,dynamic> p) async {final a=p['action']?.toString()??'parse_json';final raw=p['data']?.toString()??'';try{switch(a){case 'parse_json':return StepResult.success('تم تحليل JSON.',data:jsonDecode(raw));case 'parse_csv':final lines=raw.split(RegExp(r'\r?\n')).where((e)=>e.trim().isNotEmpty).toList();if(lines.isEmpty)return StepResult.failure('CSV فارغ.');final h=lines.first.split(',');final rows=lines.skip(1).map((x)=>x.split(',')).toList();return StepResult.success('تم تحليل '+rows.length.toString()+' صف.',data:{'headers':h,'rows':rows});case 'filter':final d=jsonDecode(raw);if(d is! List)return StepResult.failure('filter يحتاج قائمة JSON.');final k=p['filter_key']?.toString()??'';final v=p['filter_value'];final f=d.where((x)=>x is Map&&x[k]?.toString()==v?.toString()).toList();return StepResult.success('تمت التصفية: '+f.length.toString()+' عنصر.',data:f);default:return StepResult.failure('إجراء data غير معروف: '+a);}}catch(e){return StepResult.failure('بيانات غير صالحة: '+e.toString());}}
}
